void sobel(const uint8_t *input, uint8_t *output, int width, int height)
{
  /* Knob Variables Declaration Start */
  float loop_perforation_factor = 1.0;  // Range: 0.1 to 1.0 (Real)
  int precision_scale = 1;             // Range: 0 to 1 (Integer)
  int early_exit_threshold = 0;        // Range: 0 to 255 (Integer)
  int quantize_enabled = 0;            // 0 = disabled, 1 = enabled (Integer)
  int shift_bits = 0;                  // Range: 0 to 4 (Integer)
  /* Knob Variables Declaration End */

  int perforated_height = height * loop_perforation_factor;
  int perforated_width = width * loop_perforation_factor;

  for (int y = 0; y < perforated_height; y++) {  // Loop Perforation
    for (int x = 0; x < perforated_width; x++) {  // Loop Perforation

      if (x == 0 || x == width - 1 || y == 0 || y == height - 1) {
        output[y * width + x] = 0;
        continue;
      }

      int p00 = input[(y-1)*width + (x-1)];
      int p01 = input[(y-1)*width +  x   ];
      int p02 = input[(y-1)*width + (x+1)];
      int p10 = input[ y   *width + (x-1)];
      int p12 = input[ y   *width + (x+1)];
      int p20 = input[(y+1)*width + (x-1)];
      int p21 = input[(y+1)*width +  x   ];
      int p22 = input[(y+1)*width + (x+1)];

      // Precision Scaling: Reduce precision of intermediate calculations
      int gx, gy;
      if (precision_scale == 1) {
        // Full precision (baseline)
        gx = -p00 + p02 - 2*p10 + 2*p12 - p20 + p22;
        gy =  p00 + 2*p01 + p02 - p20 - 2*p21 - p22;
      } else {
        // Reduced precision (e.g., 8-bit arithmetic)
        gx = ((-p00 + p02 - 2*p10 + 2*p12 - p20 + p22) >> 1);
        gy = ((p00 + 2*p01 + p02 - p20 - 2*p21 - p22) >> 1);
      }

      // Early-Exit Approximation: Skip low-gradient regions
      if (early_exit_threshold > 0 && abs(gx) + abs(gy) < early_exit_threshold) {
        output[y * width + x] = 0;
        continue;
      }

      int mag = abs(gx) + abs(gy);
      if (mag > 255) mag = 255;

      // 4-Bit Quantization: Reduce gradient magnitude to 4 bits
      if (quantize_enabled) {
        mag = mag >> shift_bits;
      }

      output[y * width + x] = (uint8_t)mag;
    }
  }
}
